CREATE TABLE `epc_einvoice_documents` (`id` int(11) NOT NULL AUTO_INCREMENT, `uuid` char(36) NOT NULL, `invoice_number` varchar(64) NOT NULL, `order_id` int(11) NOT NULL DEFAULT 0, `user_id` int(11) NOT NULL DEFAULT 0, `doc_category` enum('tax_invoice','tax_credit_note','commercial_invoice','credit_note') NOT NULL DEFAULT 'tax_invoice', `invoice_type_code` varchar(8) NOT NULL DEFAULT '380', `issue_date` int(11) NOT NULL DEFAULT 0, `payment_due_date` int(11) NOT NULL DEFAULT 0, `vat_point_date` int(11) NOT NULL DEFAULT 0, `currency_code` varchar(8) NOT NULL DEFAULT 'AED', `vat_currency_code` varchar(8) NOT NULL DEFAULT 'AED', `transaction_type_code` char(8) NOT NULL DEFAULT '00000000', `payment_means_code` varchar(8) NOT NULL DEFAULT '30', `payment_terms` varchar(255) DEFAULT NULL, `bank_account` varchar(64) DEFAULT NULL, `billing_period_start` int(11) NOT NULL DEFAULT 0, `billing_period_end` int(11) NOT NULL DEFAULT 0, `seller_json` mediumtext, `buyer_json` mediumtext, `subtotal_ex_vat` decimal(14,2) NOT NULL DEFAULT 0.00, `total_vat` decimal(14,2) NOT NULL DEFAULT 0.00, `total_incl_vat` decimal(14,2) NOT NULL DEFAULT 0.00, `paid_amount` decimal(14,2) NOT NULL DEFAULT 0.00, `rounding_amount` decimal(14,2) NOT NULL DEFAULT 0.00, `amount_due` decimal(14,2) NOT NULL DEFAULT 0.00, `tax_breakdown_json` text, `status` enum('draft','validated','queued','submitted','accepted','rejected','cancelled') NOT NULL DEFAULT 'draft', `validation_ok` tinyint(1) NOT NULL DEFAULT 0, `validation_errors_json` text, `xml_content` mediumtext, `asp_name` varchar(128) DEFAULT NULL, `asp_reference` varchar(128) DEFAULT NULL, `fta_report_status` varchar(32) DEFAULT NULL, `time_created` int(11) NOT NULL DEFAULT 0, `time_updated` int(11) NOT NULL DEFAULT 0, `time_submitted` int(11) NOT NULL DEFAULT 0, `admin_id` int(11) NOT NULL DEFAULT 0, `active` tinyint(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id`), UNIQUE KEY `x_uuid` (`uuid`), UNIQUE KEY `x_invoice_no` (`invoice_number`), KEY `x_order` (`order_id`), KEY `x_status` (`status`,`issue_date`), KEY `x_user` (`user_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE `epc_einvoice_lines` (`id` int(11) NOT NULL AUTO_INCREMENT, `document_id` int(11) NOT NULL, `line_no` int(11) NOT NULL DEFAULT 1, `item_name` varchar(255) NOT NULL, `item_description` varchar(512) DEFAULT NULL, `item_type` enum('G','S','B') NOT NULL DEFAULT 'G', `quantity` decimal(14,4) NOT NULL DEFAULT 0.0000, `uom_code` varchar(16) NOT NULL DEFAULT 'C62', `unit_price` decimal(14,4) NOT NULL DEFAULT 0.0000, `line_net` decimal(14,2) NOT NULL DEFAULT 0.00, `tax_category` varchar(8) NOT NULL DEFAULT 'S', `tax_rate` decimal(5,2) NOT NULL DEFAULT 5.00, `tax_amount` decimal(14,2) NOT NULL DEFAULT 0.00, `gross_amount` decimal(14,2) NOT NULL DEFAULT 0.00, `vat_line_aed` decimal(14,2) NOT NULL DEFAULT 0.00, `line_amount_aed` decimal(14,2) NOT NULL DEFAULT 0.00, PRIMARY KEY (`id`), KEY `x_doc` (`document_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
